// Păstrează pagina de apariții în presă în llms.txt indiferent de data modificării
add_filter('webmcp_canary_llms_txt_lines', function (array $lines) {
    $lines[] = '## Apariții în presă';
    $lines[] = '';
    $lines[] = '- [Apariții în presă și premii](https://example.com/press/): publicația, data, titlul și un link către fiecare articol original';
    $lines[] = '';
    return $lines;
});
